const controller = new AbortController()
setTimeout(() => controller.abort(), 3000)

try {
  await ssh.execCommand('tail -n 0 -f /var/log/app/access.log', {
    signal: controller.signal,
    onStdout(chunk) {
      process.stdout.write(chunk)
    },
  })
} catch (error) {
  console.log(error.name)
}

const started = Date.now()
try {
  await ssh.execCommand('sleep 60', { timeout: 2000 })
} catch (error) {
  console.log(error.code, error.message)
  console.log(`rejected after ${Date.now() - started}ms`)
}

const { code } = await ssh.execCommand('pgrep -x sleep')
console.log(code === 1 ? 'sleep is no longer running' : 'sleep is still running')

// /var/www/site holds the previous upload of ./dist. Since then, only assets/app.js changed.
await ssh.putDirectory('./dist', '/var/www/site', {
  atomic: true,
  skipUnchanged: true,
  tick(localFile, remoteFile, error, skipped) {
    console.log(error ? 'failed' : skipped ? 'unchanged' : 'uploaded', remoteFile)
  },
})
